function s(v) { return String(v == null ? '' : v).trim(); }
const inv = $input.all().map(function (i) { return i.json; });
if (inv.length < 100) { throw new Error('ABORT: INVESTORS only ' + inv.length + ' rows'); }
const live = inv.filter(function (r) { return s(r.investor) && s(r.do_not_contact).toLowerCase() !== 'yes'; });
const out = live.map(function (r) {
  return [s(r.investor), s(r.sector).slice(0, 90), s(r.stage).slice(0, 40), s(r.cheque_inr_cr).slice(0, 30)];
});
return [{ json: { total: inv.length, contactable: live.length, rows: out } }];
